// Command ptyrec records a PTY session to a raw byte file plus an NDJSON
// timing sidecar, and (as a subcommand) replays a raw file through a
// headless VT100 emulator to dump the final screen grid.
//
// Usage:
//
//	ptyrec [-o FILE] -- <command> [args...]
//	ptyrec replay [--cols N] [--rows N] <rawfile>
package main

import (
	"fmt"
	"os"
)

func main() {
	if len(os.Args) > 1 && os.Args[1] == "replay" {
		if err := runReplay(os.Args[2:]); err != nil {
			fmt.Fprintln(os.Stderr, "ptyrec replay:", err)
			os.Exit(1)
		}
		return
	}
	os.Exit(runRecord(os.Args[1:]))
}

