package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"os/signal"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/creack/pty"
	"golang.org/x/term"
)

// runRecord implements the top-level `ptyrec [-o FILE] -- <command> [args...]`
// invocation. It returns the process exit code to use.
func runRecord(args []string) int {
	outFile, cmdArgs, err := parseRecordArgs(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, "ptyrec:", err)
		return 2
	}
	if len(cmdArgs) == 0 {
		fmt.Fprintln(os.Stderr, "ptyrec: missing command after --")
		return 2
	}

	if outFile == "" {
		outFile = fmt.Sprintf("session-%d.raw", time.Now().Unix())
	}
	timingFile := strings.TrimSuffix(outFile, ".raw") + ".timing"

	rawF, err := os.Create(outFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "ptyrec: create raw file:", err)
		return 1
	}
	defer rawF.Close()

	timingF, err := os.Create(timingFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "ptyrec: create timing file:", err)
		return 1
	}
	defer timingF.Close()
	timingW := bufio.NewWriter(timingF)
	defer timingW.Flush()

	cols, rows := queryWinsize()

	c := exec.Command(cmdArgs[0], cmdArgs[1:]...)
	ptmx, err := pty.StartWithSize(c, &pty.Winsize{Cols: uint16(cols), Rows: uint16(rows)})
	if err != nil {
		fmt.Fprintln(os.Stderr, "ptyrec: start pty:", err)
		return 1
	}
	defer ptmx.Close()

	// --- raw mode for our own stdin, restored on ALL exit paths ---
	var restoreStdin func()
	stdinFd := int(os.Stdin.Fd())
	if term.IsTerminal(stdinFd) {
		oldState, err := term.MakeRaw(stdinFd)
		if err == nil {
			restoreStdin = func() { term.Restore(stdinFd, oldState) }
			defer restoreStdin()
		}
	}

	// --- signal handling: SIGWINCH resizes the pty; other terminating
	// signals just need to let the raw-mode restore (deferred above) run,
	// so we restore explicitly then re-raise / exit.
	sigCh := make(chan os.Signal, 4)
	signal.Notify(sigCh, syscall.SIGWINCH, syscall.SIGINT, syscall.SIGTERM, syscall.SIGHUP)
	done := make(chan struct{})
	go func() {
		for {
			select {
			case sig := <-sigCh:
				switch sig {
				case syscall.SIGWINCH:
					nc, nr := queryWinsize()
					pty.Setsize(ptmx, &pty.Winsize{Cols: uint16(nc), Rows: uint16(nr)})
				default:
					if restoreStdin != nil {
						restoreStdin()
					}
					os.Exit(128 + signalNum(sig))
				}
			case <-done:
				return
			}
		}
	}()
	defer close(done)
	// Trigger an initial resize check in case the size changed between
	// query and pty creation.
	sigCh <- syscall.SIGWINCH

	start := time.Now()
	var timingMu sync.Mutex
	writeTiming := func(n int) {
		timingMu.Lock()
		defer timingMu.Unlock()
		ms := time.Since(start).Milliseconds()
		line, _ := json.Marshal(struct {
			T int64 `json:"t"`
			N int   `json:"n"`
		}{T: ms, N: n})
		timingW.Write(line)
		timingW.WriteByte('\n')
	}

	// stdin -> ptmx
	go func() {
		io.Copy(ptmx, os.Stdin)
	}()

	// ptmx -> stdout, tee to raw file, timing per read chunk
	copyDone := make(chan struct{})
	go func() {
		defer close(copyDone)
		buf := make([]byte, 32*1024)
		for {
			n, err := ptmx.Read(buf)
			if n > 0 {
				chunk := buf[:n]
				os.Stdout.Write(chunk)
				rawF.Write(chunk)
				writeTiming(n)
			}
			if err != nil {
				return
			}
		}
	}()

	waitErr := c.Wait()

	// Drain remaining output: give the copy goroutine a moment to finish
	// reading whatever is still buffered in the pty master after the
	// child exits, then close ptmx to unblock the reader.
	select {
	case <-copyDone:
	case <-time.After(200 * time.Millisecond):
	}
	ptmx.Close()
	<-copyDone

	timingW.Flush()

	if restoreStdin != nil {
		restoreStdin()
		restoreStdin = nil
	}

	return exitCode(waitErr)
}

func parseRecordArgs(args []string) (outFile string, cmdArgs []string, err error) {
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			break
		}
		if a == "-o" {
			if i+1 >= len(args) {
				return "", nil, fmt.Errorf("-o requires an argument")
			}
			outFile = args[i+1]
			i += 2
			continue
		}
		if strings.HasPrefix(a, "-o=") {
			outFile = strings.TrimPrefix(a, "-o=")
			i++
			continue
		}
		return "", nil, fmt.Errorf("unexpected argument %q (expected -o FILE and/or --)", a)
	}
	return outFile, args[i:], nil
}

// queryWinsize determines the terminal size to give the child PTY: the
// current terminal's size if stdout is a TTY, else $COLUMNS/$LINES, else
// 80x24.
func queryWinsize() (cols, rows int) {
	if term.IsTerminal(int(os.Stdout.Fd())) {
		if w, h, err := term.GetSize(int(os.Stdout.Fd())); err == nil {
			return w, h
		}
	}
	cols, rows = 80, 24
	if v := os.Getenv("COLUMNS"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			cols = n
		}
	}
	if v := os.Getenv("LINES"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			rows = n
		}
	}
	return cols, rows
}

func exitCode(err error) int {
	if err == nil {
		return 0
	}
	if ee, ok := err.(*exec.ExitError); ok {
		if ws, ok := ee.Sys().(syscall.WaitStatus); ok {
			if ws.Signaled() {
				return 128 + int(ws.Signal())
			}
			return ws.ExitStatus()
		}
	}
	return 1
}

func signalNum(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return int(s)
	}
	return 1
}

