package main

import (
	"fmt"
	"os"
	"strconv"

	"github.com/hinshun/vt10x"
)

// runReplay implements `ptyrec replay [--cols N] [--rows N] <rawfile>`.
// It feeds every byte of the raw file through a headless vt10x terminal
// emulator and dumps the final grid as plain text to stdout.
func runReplay(args []string) error {
	cols, rows := 80, 24
	var rawPath string

	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "--cols":
			if i+1 >= len(args) {
				return fmt.Errorf("--cols requires an argument")
			}
			n, err := strconv.Atoi(args[i+1])
			if err != nil {
				return fmt.Errorf("--cols: %w", err)
			}
			cols = n
			i += 2
		case "--rows":
			if i+1 >= len(args) {
				return fmt.Errorf("--rows requires an argument")
			}
			n, err := strconv.Atoi(args[i+1])
			if err != nil {
				return fmt.Errorf("--rows: %w", err)
			}
			rows = n
			i += 2
		default:
			if rawPath != "" {
				return fmt.Errorf("unexpected extra argument %q", a)
			}
			rawPath = a
			i++
		}
	}
	if rawPath == "" {
		return fmt.Errorf("usage: ptyrec replay [--cols N] [--rows N] <rawfile>")
	}

	data, err := os.ReadFile(rawPath)
	if err != nil {
		return fmt.Errorf("read raw file: %w", err)
	}

	// vt10x has been observed to panic on certain malformed/edge-case
	// escape sequences; recover so replay still prints whatever grid
	// state was reached before the panic, and reports it as a finding.
	term := vt10x.New(vt10x.WithSize(cols, rows))

	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintf(os.Stderr, "ptyrec replay: vt10x panicked mid-stream: %v\n", r)
			}
		}()
		_, werr := term.Write(data)
		if werr != nil {
			fmt.Fprintf(os.Stderr, "ptyrec replay: vt10x write error: %v\n", werr)
		}
	}()

	printGrid(term, cols, rows)
	return nil
}

func printGrid(term vt10x.Terminal, cols, rows int) {
	term.Lock()
	defer term.Unlock()
	for y := 0; y < rows; y++ {
		line := make([]rune, cols)
		for x := 0; x < cols; x++ {
			g := term.Cell(x, y)
			if g.Char == 0 {
				line[x] = ' '
			} else {
				line[x] = g.Char
			}
		}
		fmt.Println(string(line))
	}
}

